// Code node: Normalizar Payload GHL
// Versão 2.0 - Atualizado para extrair TODOS os campos relevantes do GHL (exceto attribution)

const body = $input.item.json.body;
const headers = $input.item.json.headers;

// ========================================
// 1. DADOS BÁSICOS DO CONTATO
// ========================================

const contactId = body["Lead ID"] || body.contact_id || null;

const fullName = body["Contact Name"] || body.full_name || 
                 `${body["First Name"] || body.first_name || ''} ${body["Last Name"] || body.last_name || ''}`.trim() || 
                 '';

const email = body["Email"] || body.email || '';
const phone = body["Phone"] || body.phone || '';

// ========================================
// 2. DADOS DEMOGRÁFICOS DO CONTATO
// ========================================

const sexo = body["Sexo"] || '';
const city = body["city"] || body.city || '';
const state = body["state"] || body.state || '';
const country = body["country"] || body.country || 'BR';
const dateOfBirth = body["date_of_birth"] || '';
const fullAddress = body["full_address"] || '';
const contactType = body["contact_type"] || '';
const contactSource = body["contact_source"] || body["Fonte do Contato"] || '';

// ========================================
// 3. PIPELINE E STAGE
// ========================================

const customData = body.customData || {};

const pipelineName = customData.Nome_Pipeline || 
                     body.pipeline_name || 
                     body["Pipeline Name"] || '';

const pipelineStage = customData.Estagio_Pipeline || 
                      body.pipleline_stage || 
                      body.pipeline_stage || 
                      body["Pipeline Stage"] || '';

const pipelineId = body.pipeline_id || body["Pipeline ID"] || '';

// ========================================
// 4. DADOS CLÍNICOS / SDR
// ========================================

// Tratamento de Interesse (tentar várias possibilidades)
const tratamentoInteresse = body["Primeiro Tratamento de Interesse"] ||
                            body["Tratamentos de interesse"] ||
                            body["Tratamento de interesse"] ||
                            customData.Tratamentos ||
                            body.tratamentos || 
                            '';

const queixaPrincipal = body["Queixa Principal"] || '';
const anotacoesSDR = body["Anotações SDR"] || '';
const qualificacaoSDR = body["Qualificação SDR"] || '';
const temExames = body["Tem Exames?"] || [];
const cobrouConsulta = body["Cobrou Consulta"] || '';
const passouValores = body["Passou Valores?"] || '';
const condicoesPagamento = body["Condições de Pagamento?"] || '';

// Nota e Análise existentes (se já preenchidos)
const notaSDR = body["Nota SDR"] || '';
const analiseSDR = body["Análise SDR"] || '';
const transcricaoSDRExistente = body["Transcrição SDR"] || '';

// Closer fields
const notaCloser = body["Nota Closer"] || '';
const avaliacaoCloser = body["Avaliação Closer"] || '';
const transcricaoCloser = body["Transcrição Closer"] || '';

// ========================================
// 5. DADOS DE MARKETING / CAPTAÇÃO
// ========================================

const origemCaptacao = body["Origem de Captação"] || body.opportunity_source || body.source || '';
const fonteContato = body["Fonte do Contato"] || body.contact_source || '';
const ultimoCanalContato = body["Ultimo Canal de Contato"] || '';
const perfilCaptacao = body["Perfil de Captação"] || '';

// Primeiro (First Touch)
const primeiroAdId = body["Primeiro - Ad ID"] || '';
const primeiroAdName = body["Primeiro - Ad Name"] || '';
const primeiroMedium = body["Primeiro - Medium"] || '';
const primeiroSessionSource = body["Primeiro - Session Source"] || '';
const primeiroURL = body["Primeiro - URL"] || '';
const primeiroMensagem = body["Primeiro -  Mensagem"] || body["Primeiro - Mensagem"] || '';
const primeiroCampaign = body["Primeiro - Campaign"] || body["Primeiro - UTM Campaign"] || '';
const primeiroCtwClid = body["Primeiro - Ctwa Clid"] || '';

// Last (Last Touch)
const lastAdId = body["Last - Ad ID"] || '';
const lastAdName = body["Last - Ad Name"] || '';
const lastMedium = body["Last - Medium"] || '';
const lastSessionSource = body["Last - Session Source"] || '';
const lastURL = body["Last - URL"] || '';
const lastMensagem = body["Last - Mensagem"] || '';
const lastCampaign = body["Last - Campaign"] || body["Last - UTM Campaign"] || '';
const lastCtwClid = body["Last - Ctwa Clid"] || '';

// ========================================
// 6. DADOS DE OPORTUNIDADE
// ========================================

const opportunityId = body.id || '';
const opportunityName = body.opportunity_name || '';
const opportunityStatus = body.status || '';
const opportunitySource = body.opportunity_source || body.source || '';
const leadValue = customData.Valor || 
                  body.value || 
                  body["Valor"] || 
                  body.lead_value || 
                  0;

// Datas da oportunidade
const dataAprovacao = customData.aprovacao || '';
const dataCriacao = customData.criacao || body.date_created || '';
const dataAgendamento = customData.agendamento || '';
const dataComparecimento = customData.comparecimento || '';

// ========================================
// 7. LOCATION (expandido)
// ========================================

const locationData = body.location || {};
const locationId = body["Location ID"] || locationData.id || 'mZpTdAZQH6MbUWzvsLiS';
const locationName = locationData.name || '';
const locationAddress = locationData.address || '';
const locationCity = locationData.city || '';
const locationState = locationData.state || '';
const locationFullAddress = locationData.fullAddress || '';
const locationPostalCode = locationData.postalCode || '';

// ========================================
// 8. USER / SDR DATA
// ========================================

const userData = body.user || {};
const userFirstName = body["User First Name"] || userData.firstName || '';
const userLastName = body["User Last Name"] || userData.lastName || '';
const userEmail = body["User Email"] || userData.email || '';

// Opportunity Owner (pode ser diferente do user)
const opportunityOwner = body.opportunity_owner || body["Opportunity Owner"] || {};
const ownerName = typeof opportunityOwner === 'string' ? opportunityOwner : 
                  (opportunityOwner.name || `${userFirstName} ${userLastName}`.trim() || '');
const ownerEmail = typeof opportunityOwner === 'object' ? (opportunityOwner.email || userEmail) : userEmail;

// ========================================
// 9. TAGS (converter string para array)
// ========================================

let tags = [];
if (body.tags) {
  if (Array.isArray(body.tags)) {
    tags = body.tags;
  } else if (typeof body.tags === 'string') {
    tags = body.tags.split(',').map(tag => tag.trim()).filter(tag => tag);
  }
}

// ========================================
// 10. CRIAR ESTRUTURA NORMALIZADA
// ========================================

const normalizedBody = {
  // === Identificadores ===
  contact_id: contactId,
  opportunity_id: opportunityId,

  // === Dados do Contato ===
  full_name: fullName,
  email: email,
  phone: phone,
  sexo: sexo,
  date_of_birth: dateOfBirth,

  // === Endereço do Contato ===
  city: city,
  state: state,
  country: country,
  full_address: fullAddress,
  contact_type: contactType,
  contact_source: contactSource,

  // === Pipeline e Stage ===
  pipeline_name: pipelineName,
  pipleline_stage: pipelineStage, // mantendo typo do GHL
  pipeline_stage: pipelineStage,  // versão correta também
  pipeline_id: pipelineId,

  // === Dados Clínicos / SDR ===
  tratamento_interesse: tratamentoInteresse,
  queixa_principal: queixaPrincipal,
  anotacoes_sdr: anotacoesSDR,
  qualificacao_sdr: qualificacaoSDR,
  tem_exames: temExames,
  cobrou_consulta: cobrouConsulta,
  passou_valores: passouValores,
  condicoes_pagamento: condicoesPagamento,

  // === Notas/Análises Existentes ===
  nota_sdr_existente: notaSDR,
  analise_sdr_existente: analiseSDR,
  transcricao_sdr_existente: transcricaoSDRExistente,
  nota_closer_existente: notaCloser,
  avaliacao_closer_existente: avaliacaoCloser,
  transcricao_closer_existente: transcricaoCloser,

  // === Dados de Marketing / Captação ===
  origem_captacao: origemCaptacao,
  fonte_contato: fonteContato,
  ultimo_canal_contato: ultimoCanalContato,
  perfil_captacao: perfilCaptacao,

  // === First Touch ===
  primeiro_ad_id: primeiroAdId,
  primeiro_ad_name: primeiroAdName,
  primeiro_medium: primeiroMedium,
  primeiro_session_source: primeiroSessionSource,
  primeiro_url: primeiroURL,
  primeiro_mensagem: primeiroMensagem,
  primeiro_campaign: primeiroCampaign,
  primeiro_ctw_clid: primeiroCtwClid,

  // === Last Touch ===
  last_ad_id: lastAdId,
  last_ad_name: lastAdName,
  last_medium: lastMedium,
  last_session_source: lastSessionSource,
  last_url: lastURL,
  last_mensagem: lastMensagem,
  last_campaign: lastCampaign,
  last_ctw_clid: lastCtwClid,

  // === Oportunidade ===
  opportunity_name: opportunityName,
  opportunity_status: opportunityStatus,
  opportunity_source: opportunitySource,
  lead_value: leadValue,

  // === Datas ===
  data_criacao: dataCriacao,
  data_aprovacao: dataAprovacao,
  data_agendamento: dataAgendamento,
  data_comparecimento: dataComparecimento,

  // === Location (expandido) ===
  location: {
    id: locationId,
    name: locationName,
    address: locationAddress,
    city: locationCity,
    state: locationState,
    fullAddress: locationFullAddress,
    postalCode: locationPostalCode
  },

  // === User / SDR ===
  user: {
    firstName: userFirstName,
    lastName: userLastName,
    email: userEmail
  },

  // === Opportunity Owner ===
  opportunity_owner: {
    name: ownerName,
    email: ownerEmail
  },

  // SDR nome (atalho para usar nos nodes seguintes)
  sdr_nome: ownerName || `${userFirstName} ${userLastName}`.trim(),
  sdr_email: ownerEmail || userEmail,

  // === Tags ===
  tags: tags,

  // === Custom Data Original (para referência) ===
  customData: {
    ...customData,
    tratamento: tratamentoInteresse,
    tratamento_interesse: tratamentoInteresse
  }
};

// ========================================
// 11. RETORNAR NO FORMATO ESPERADO
// ========================================

return [{
  json: {
    body: normalizedBody,
    headers: headers,
    params: $input.item.json.params || {},
    query: $input.item.json.query || {}
  }
}];

// Continuar paginação a partir do node ACC
const inItem = $input.first()?.json || {};
const BASE = 'https://services.leadconnectorhq.com';

// Token: ideal vir de um Set/credencial, aqui deixo fixo só pra teste
const authToken = 'YOUR_GHL_API_TOKEN';

// Pegar dados do ACC (que mantém todos os campos anteriores)
const conversationId =
  inItem?.conversation_id ||
  inItem?.conversationId ||
  inItem?.ConversationId ||
  inItem?.messages?.messages?.[0]?.conversationId ||
  null;

const locationId =
  inItem?.locationId ||
  inItem?.messages?.messages?.[0]?.locationId ||
  null;

// ✅ DEFINIR FUNÇÕES ANTES DE USAR
const shouldKeep = (m) =>
  !m?.body?.startsWith('#switch') &&
  m?.body !== 'Opportunity updated' &&
  (m?.body || m?.attachments?.length > 0);

const pick = (m) => {
  const result = {
    id: m.id,
    direction: m.direction,
    messageType: m.messageType,
    body: m.body,
    dateAdded: m.dateAdded,
    source: m.source,
    status: m.status,
    userId: m.userId,
  };

  // Só adiciona attachments se tiver algum
  if (m.attachments?.length > 0) {
    result.attachments = m.attachments;
  }

  return result;
};


// Pegar dados de paginação do ACC
const accString = inItem?.acc || '[]';
let acc = [];

try {
  acc = JSON.parse(accString);
} catch (e) {
  acc = Array.isArray(accString) ? accString : [];

  if (acc.length === 0 && inItem?.messages?.messages) {
    acc = Array.isArray(inItem.messages.messages) ? inItem.messages.messages : [];
  }
}

// ✅ FILTRAR E APLICAR PICK NO ACC INICIAL
acc = acc.filter(shouldKeep).map(pick);

const lastId = inItem?.lastId1 || inItem?.messages?.lastMessageId || null;
const hasNext = inItem?.next1 === true || inItem?.next1 === 'true' || inItem?.messages?.nextPage === true;

// Contadores de falhas
let failedCount = 0;
let totalProcessed = 0;

// Se não tem próxima página, retornar o que já foi coletado
if (!hasNext || !lastId) {
  failedCount = acc.filter(m => m?.status === 'failed').length;
  totalProcessed = acc.length;
  const successMessages = acc.filter(m => m?.status !== 'failed');

  return [
    {
      json: {
        ...inItem,
        msgs: {
          messages: {
            messages: successMessages,
            lastMessageId: lastId,
            nextPage: false,
          },
          lastMessageId: lastId,
          nextPage: false,
        },
        meta: {
          convId: conversationId,
          locationId,
          total: successMessages.length,
          failedCount,
          failedPercent: totalProcessed > 0 ? ((failedCount / totalProcessed) * 100).toFixed(1) + '%' : '0%',
        },
      },
    },
  ];
}

if (!conversationId || !locationId) {
  console.log('DEBUG - inItem keys:', Object.keys(inItem));
  console.log('DEBUG - conversationId:', conversationId);
  console.log('DEBUG - locationId:', locationId);
  throw new Error(`Faltou conversationId ou locationId. conversationId: ${conversationId}, locationId: ${locationId}`);
}

const headers = {
  Authorization: `Bearer ${authToken}`,
  Version: '2021-04-15',
  Accept: 'application/json',
  LocationId: locationId,
};

const pageSize = 1000;
let currentLastId = lastId;
let currentHasNext = hasNext;

// Continuar paginação enquanto houver mais páginas
while (currentHasNext && currentLastId) {
  const qs = { locationId, pageSize, lastMessageId: currentLastId };

  let res;
  try {
    res = await this.helpers.request({
      method: 'GET',
      uri: `${BASE}/conversations/${conversationId}/messages`,
      qs,
      headers,
      json: true,
    });
  } catch (err) {
    const status = err?.response?.status;
    const data = err?.response?.data;
    throw new Error(`Falha HTTP ${status || ''} - ${JSON.stringify(data || err.message)}`);
  }

  const payload = res?.messages || {};
  const list = Array.isArray(payload.messages) ? payload.messages : [];

  // ✅ FILTRAR E APLICAR PICK NAS NOVAS PÁGINAS
  const filtered = list.filter(shouldKeep).map(pick);
  acc = acc.concat(filtered);

  currentLastId = payload.lastMessageId ?? null;
  currentHasNext = Boolean(payload.nextPage);

  if (acc.length > 100000) throw new Error('Limite de segurança (100k msgs) atingido');
}

// Contabilizar falhas
failedCount = acc.filter(m => m?.status === 'failed').length;
totalProcessed = acc.length;

// Remover mensagens failed do array final
const successMessages = acc.filter(m => m?.status !== 'failed');

return [{
  json: {
    // Só campos essenciais para próximos nodes
    traceId: inItem.traceId,
    conversation_id: conversationId,
    locationId: locationId,

    // Mensagens processadas
    msgs: successMessages,

    // Metadados
    meta: {
      total: successMessages.length,
      failedCount,
      failedPercent: totalProcessed > 0 ? ((failedCount / totalProcessed) * 100).toFixed(1) + '%' : '0%',
      lastMessageId: currentLastId,
      hasMore: currentHasNext,
    },
  },
}];

// ==== CONFIG =========================================
const TZ = 'America/Sao_Paulo';
const LOCALE = 'pt-BR';

// =====================================================

const inputData = $input.first()?.json || {};

// Nome do contato vem do node anterior
const contactName = $('Preparar Dados').first().json.contact_name || 'Lead';

// Busca TODAS as mensagens (incluindo páginas aninhadas)
function getAllMessages() {
  const found = [];

  function findMessages(obj, depth = 0) {
    if (!obj || typeof obj !== 'object' || depth > 10) return;

    if (Array.isArray(obj)) {
      for (const item of obj) {
        if (item && item.id && item.direction && item.hasOwnProperty('body')) {
          found.push(item);
        } else if (item && typeof item === 'object') {
          findMessages(item, depth + 1);
        }
      }
      return;
    }

    for (const key of Object.keys(obj)) {
      const val = obj[key];
      if (key === 'messages' && Array.isArray(val)) {
        findMessages(val, depth + 1);
      } else if (val && typeof val === 'object') {
        findMessages(val, depth + 1);
      }
    }
  }

  findMessages(inputData);

  const uniqueMap = new Map();
  for (const msg of found) {
    if (msg.id && !uniqueMap.has(msg.id)) {
      uniqueMap.set(msg.id, msg);
    }
  }

  return Array.from(uniqueMap.values());
}

// Formata data compacta: "13/01 16:48"
function fmtDate(iso) {
  try {
    const d = new Date(iso);
    return d.toLocaleString(LOCALE, {
      timeZone: TZ,
      day: '2-digit',
      month: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    }).replace(',', '');
  } catch {
    return '';
  }
}

// Detecta tipo de anexo
function getAttachmentType(url) {
  if (typeof url !== 'string') return 'arquivo';
  const lower = url.toLowerCase();
  if (lower.includes('.mp4') || lower.includes('.mov') || lower.includes('.avi')) return 'video';
  if (lower.includes('.mp3') || lower.includes('.ogg') || lower.includes('.opus') || lower.includes('.m4a') || lower.includes('.aac') || lower.includes('.wav')) return 'audio';
  if (lower.includes('.jpeg') || lower.includes('.jpg') || lower.includes('.png') || lower.includes('.gif') || lower.includes('.webp')) return 'imagem';
  if (lower.includes('.pdf')) return 'pdf';
  if (lower.includes('.doc') || lower.includes('.docx') || lower.includes('.xls') || lower.includes('.xlsx') || lower.includes('.ppt') || lower.includes('.pptx') || lower.includes('.txt')) return 'documento';
  return 'arquivo';
}

// ========== CLASSIFICAÇÃO DE MENSAGENS ==========

function isSystemEvent(msg) {
  if ([28, 31, 32, 33, 34, 35].includes(msg?.type)) return true;

  const systemTypes = [
    'TYPE_ACTIVITY_OPPORTUNITY',
    'TYPE_ACTIVITY_APPOINTMENT',
    'TYPE_ACTIVITY_PAYMENT',
    'TYPE_ACTIVITY_INVOICE',
    'TYPE_ACTIVITY_TASK',
    'TYPE_ACTIVITY_NOTE',
    'TYPE_INTERNAL_COMMENT'
  ];
  if (systemTypes.includes(msg?.messageType)) return true;

  return false;
}

function isUsefulMessage(msg) {
  if (isSystemEvent(msg)) return false;

  const body = (msg?.body ?? '').toString().trim();
  if (body.startsWith('#switch|')) return false;

  const hasText = body.length > 0;
  const hasAttachments = Array.isArray(msg?.attachments) && msg.attachments.length > 0;

  return hasText || hasAttachments;
}

// ========== EXTRAÇÃO DE EVENTOS ==========

function extractEvents(allMsgs) {
  const eventos = [];

  for (const msg of allMsgs) {
    if (!isSystemEvent(msg)) continue;

    const data = fmtDate(msg?.dateAdded);
    const body = (msg?.body ?? '').toString().trim();
    const msgType = msg?.messageType || '';
    const type = msg?.type;
    const bodyLower = body.toLowerCase();

    if (type === 31 || msgType === 'TYPE_ACTIVITY_APPOINTMENT') {
      eventos.push({
        data: data,
        tipo: 'AGENDAMENTO',
        detalhe: body || 'Agendamento criado'
      });
    }
    else if (type === 32 || msgType === 'TYPE_ACTIVITY_PAYMENT') {
      eventos.push({
        data: data,
        tipo: 'PAGAMENTO',
        detalhe: body || 'Pagamento realizado'
      });
    }
    else if (type === 33 || msgType === 'TYPE_ACTIVITY_INVOICE') {
      eventos.push({
        data: data,
        tipo: 'FATURA',
        detalhe: body || 'Fatura gerada'
      });
    }
    else if (type === 28 || msgType === 'TYPE_ACTIVITY_OPPORTUNITY') {
      if (bodyLower === 'opportunity updated') continue;

      let tipoEvento = 'STATUS';

      if (bodyLower.includes('status changed')) {
        tipoEvento = 'STATUS_CHANGED';
      } else if (bodyLower.includes('created')) {
        tipoEvento = 'LEAD_CRIADO';
      } else if (bodyLower.includes('compareceu')) {
        tipoEvento = 'COMPARECEU';
      } else if (bodyLower.includes('não compareceu') || bodyLower.includes('no show')) {
        tipoEvento = 'NAO_COMPARECEU';
      } else if (bodyLower.includes('ganho') || bodyLower.includes('won') || bodyLower.includes('fechado')) {
        tipoEvento = 'GANHO';
      } else if (bodyLower.includes('perdido') || bodyLower.includes('lost')) {
        tipoEvento = 'PERDIDO';
      }

      eventos.push({
        data: data,
        tipo: tipoEvento,
        detalhe: body
      });
    }
  }

  return eventos.sort((a, b) => (a.data || '').localeCompare(b.data || ''));
}

// ========== DETERMINA ROLE DA MENSAGEM ==========

function getMessageRole(msg) {
  // Inbound = sempre LEAD
  if (msg?.direction === 'inbound') return 'LEAD';

  // Outbound com source workflow = WORKFLOW
  if (msg?.source === 'workflow') return 'WORKFLOW';

  // Outbound de humano = SDR
  return 'SDR';
}

// ========== PROCESSAMENTO ==========

const allRawMessages = getAllMessages()
  .sort((a, b) => new Date(a?.dateAdded || 0) - new Date(b?.dateAdded || 0));

const chatMessages = allRawMessages.filter(isUsefulMessage);
const eventos = extractEvents(allRawMessages);

// Contadores globais para indexar arquivos
let audioIndex = 0;
let imagemIndex = 0;
let pdfIndex = 0;
let docIndex = 0;
let videoIndex = 0;
let arquivoIndex = 0;

// Arrays para arquivos a processar
const audiosParaTranscrever = [];
const imagensParaDescrever = [];
const documentosParaLer = [];

const chatLines = [];

for (const msg of chatMessages) {
  const when = fmtDate(msg?.dateAdded);
  const role = getMessageRole(msg);
  let text = (msg?.body ?? '').toString().trim();

  // Processa anexos
  if (Array.isArray(msg?.attachments) && msg.attachments.length > 0) {
    const anexos = [];

    for (const att of msg.attachments) {
      const url = typeof att === 'string' ? att : att?.url || '';
      const tipo = getAttachmentType(url);

      const baseInfo = {
        url: url,
        role: role,
        timestamp: msg?.dateAdded,
        messageId: msg?.id
      };

      if (tipo === 'audio') {
        audioIndex++;
        const id = 'AUDIO_' + audioIndex;
        anexos.push('[' + id + ']');
        audiosParaTranscrever.push({ id, ...baseInfo });
      } 
      else if (tipo === 'imagem') {
        imagemIndex++;
        const id = 'IMAGEM_' + imagemIndex;
        anexos.push('[' + id + ']');
        imagensParaDescrever.push({ id, ...baseInfo });
      }
      else if (tipo === 'pdf') {
        pdfIndex++;
        const id = 'PDF_' + pdfIndex;
        anexos.push('[' + id + ']');
        documentosParaLer.push({ id, tipo: 'pdf', ...baseInfo });
      }
      else if (tipo === 'documento') {
        docIndex++;
        const id = 'DOC_' + docIndex;
        anexos.push('[' + id + ']');
        documentosParaLer.push({ id, tipo: 'documento', ...baseInfo });
      }
      else if (tipo === 'video') {
        videoIndex++;
        anexos.push('[VIDEO_' + videoIndex + ']');
      }
      else {
        arquivoIndex++;
        anexos.push('[ARQUIVO_' + arquivoIndex + ']');
      }
    }

    if (text) {
      text = text + ' ' + anexos.join(' ');
    } else {
      text = anexos.join(' ');
    }
  }

  chatLines.push('[' + when + '] ' + role + ': ' + text);
}

// Monta transcrição
const transcricao = chatLines.join('\n');

// Resumo com período correto (primeira → última mensagem)
const resumo = {
  total: chatMessages.length,
  lead: chatMessages.filter(m => m.direction === 'inbound').length,
  sdr: chatMessages.filter(m => m.direction === 'outbound' && m.source !== 'workflow').length,
  workflow: chatMessages.filter(m => m.source === 'workflow').length,
  periodo: chatMessages.length > 0 ? {
    inicio: fmtDate(chatMessages[0]?.dateAdded),
    fim: fmtDate(chatMessages[chatMessages.length - 1]?.dateAdded)
  } : null
};

// ========== OUTPUT ESTRUTURADO ==========
return [{
  json: {
    transcricao: transcricao,
    lead_nome: contactName,
    resumo: resumo,
    eventos: eventos,
    audios_para_transcrever: audiosParaTranscrever,
    imagens_para_descrever: imagensParaDescrever,
    documentos_para_ler: documentosParaLer
  }
}];

// Truncar transcrição antes de enviar para Claude
// Limite: 20.000 caracteres (aprox 5k tokens) - deixa espaço para system prompt e resposta
// Claude Sonnet 4 tem limite de 8.192 tokens total

const input = $input.first().json;
const transcricao = input.transcricao_markdown || input.transcricao_texto || '';

// Limite de caracteres (15k = ~3.75k tokens)
// System prompt ~1k tokens + transcrição 3.75k + resposta 2k + metadados 0.5k = ~7.25k tokens total (dentro do limite de 8.192)
const LIMITE_CARACTERES = 15000;

if (!transcricao || transcricao.length === 0) {
  return [{
    json: {
      ...input,
      transcricao_markdown: '',
      transcricao_texto: '',
      transcricao_truncada: false,
      transcricao_tamanho_original: 0
    }
  }];
}

// Se já está dentro do limite, não precisa truncar
if (transcricao.length <= LIMITE_CARACTERES) {
  return [{
    json: {
      ...input,
      transcricao_markdown: transcricao,
      transcricao_texto: transcricao.replace(/^#+.*$/gm, '').replace(/\*\*/g, '').replace(/---/g, '').trim(),
      transcricao_truncada: false,
      transcricao_tamanho_original: transcricao.length
    }
  }];
}

// Truncar mantendo início (50%) e fim (50%) - mais relevante para análise
const inicio = Math.floor(LIMITE_CARACTERES * 0.5); // 7.500 caracteres
const fim = LIMITE_CARACTERES - inicio; // 7.500 caracteres

const transcricaoTruncada = 
  transcricao.substring(0, inicio) + 
  '\n\n... [TRANSCRIÇÃO TRUNCADA - ' + transcricao.length + ' caracteres totais, mostrando primeiros ' + inicio + ' e últimos ' + fim + ' caracteres] ...\n\n' +
  transcricao.substring(transcricao.length - fim);

return [{
  json: {
    ...input,
    transcricao_markdown: transcricaoTruncada,
    transcricao_texto: transcricaoTruncada.replace(/^#+.*$/gm, '').replace(/\*\*/g, '').replace(/---/g, '').trim(),
    transcricao_truncada: true,
    transcricao_tamanho_original: transcricao.length,
    transcricao_tamanho_truncado: transcricaoTruncada.length
  }
}];

// Preparar Embedding da Análise - APENAS o JSON da análise do Claude
// NÃO inclui dados do Prep Transcript para evitar arquivo gigante

const rawInput = $input.first()?.json || $input.item?.json || {};

let content = '';

// Formato do Anthropic: [{content: [{type: "text", text: "```json\n{...}\n```"}]}]
if (Array.isArray(rawInput) && rawInput.length > 0) {
  const firstItem = rawInput[0];
  if (firstItem?.content && Array.isArray(firstItem.content)) {
    const textItem = firstItem.content.find(item => item.type === 'text' && item.text);
    if (textItem && textItem.text) {
      content = textItem.text;
    }
  }
} else if (rawInput.content && Array.isArray(rawInput.content)) {
  const textItem = rawInput.content.find(item => item.type === 'text' && item.text);
  if (textItem && textItem.text) {
    content = textItem.text;
  }
}

// Remover markdown code blocks
content = content.trim();
if (content.startsWith('```json')) {
  content = content.replace(/^```json\s*/i, '');
} else if (content.startsWith('```')) {
  content = content.replace(/^```\s*/, '');
}
content = content.replace(/\s*```\s*$/, '').trim();

// Extrair JSON
const jsonMatch = content.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  content = jsonMatch[0];
}

// Parse JSON
const analiseIA = JSON.parse(content);

// Converter JSON completo para string - APENAS isso para embedding
const textoParaEmbedding = JSON.stringify(analiseIA);

// Retornar APENAS o necessário - SEM dados do Prep Transcript
return [{
  json: {
    texto_para_embedding: textoParaEmbedding
  }
}];

// Extrair Embedding - Versão Corrigida (SEM dados extras)
// Extrai JSON do Claude + embedding - APENAS campos necessários

// Buscar embedding do output do OpenAI
const embeddingArray = $json.data[0].embedding;

// Buscar dados do Merge (pode ter output bruto do Claude)
const dadosMerge = $('Merge Análise + Fallback').first()?.json || {};

// Extrair JSON do Claude se ainda estiver com markdown
let analiseIA = {};

// Verificar se tem content (output bruto do Claude)
if (dadosMerge.content && Array.isArray(dadosMerge.content)) {
  const textItem = dadosMerge.content.find(item => item.type === 'text' && item.text);
  if (textItem && textItem.text) {
    let content = textItem.text.trim();
    // Remover markdown
    if (content.startsWith('```json')) {
      content = content.replace(/^```json\s*/i, '');
    } else if (content.startsWith('```')) {
      content = content.replace(/^```\s*/, '');
    }
    content = content.replace(/\s*```\s*$/, '').trim();
    // Extrair JSON
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        analiseIA = JSON.parse(jsonMatch[0]);
      } catch (e) {
        // Se não conseguir parsear, usar objeto vazio
      }
    }
  }
} else {
  // Se já estiver extraído, usar diretamente
  analiseIA = dadosMerge;
}

// Buscar APENAS campos essenciais do Prep Transcript (sem mensagens_json, transcricao_markdown, etc)
const prepData = $('Prep Transcript').first()?.json || {};
const camposEssenciais = {
  conversation_id: prepData.conversation_id,
  contact_id: prepData.contact_id,
  contact_name: prepData.contact_name,
  contact_email: prepData.contact_email,
  contact_phone: prepData.contact_phone,
  pipeline_name: prepData.pipeline_name,
  pipeline_stage: prepData.pipeline_stage,
  sdr_nome: prepData.sdr_nome,
  agendou: prepData.agendou,
  tratamento_interesse: prepData.tratamento_interesse,
  total_mensagens: prepData.total_mensagens,
  canal: prepData.canal,
  primeira_mensagem: prepData.primeira_mensagem,
  ultima_mensagem: prepData.ultima_mensagem
};

// Combinar APENAS campos necessários
return [{
  json: {
    ...camposEssenciais,  // Apenas campos essenciais do Prep Transcript
    ...analiseIA,  // Análise do Claude (extraída)
    embedding: embeddingArray,  // Embedding do OpenAI
    embedding_dimensoes: embeddingArray?.length || 0,
    embedding_gerado_em: new Date().toISOString()
  }
}];

// Enriquecer Transcrição com Mídia Processada
const prepData = $('Prep Transcript').first().json;
let transcricao = prepData.transcricao;

// Coletar mídias processadas de todos os itens do Merge
const allItems = $input.all();
const audios = [];
const imagens = [];
const documentos = [];

for (const item of allItems) {
  const data = item.json;

  // Identificar tipo de mídia
  if (data.tipo === 'audio' && data.placeholder) {
    audios.push(data);
  } else if (data.tipo === 'imagem' && data.placeholder) {
    imagens.push(data);
  } else if ((data.tipo === 'documento' || data.tipo === 'text' || data.tipo === 'pdf') && data.placeholder) {
    documentos.push(data);
  }
}

// Substituir placeholders de áudios
if (audios.length > 0) {
  for (const audio of audios) {
    const replacement = `${audio.placeholder}\n> 🎤 **Áudio transcrito:** "${audio.transcricao || 'Erro na transcrição'}"`;
    transcricao = transcricao.replace(audio.placeholder, replacement);
  }
}

// Substituir placeholders de imagens
if (imagens.length > 0) {
  for (const img of imagens) {
    const replacement = `${img.placeholder}\n> 📸 **Imagem analisada:** ${img.descricao || 'Erro na análise'}`;
    transcricao = transcricao.replace(img.placeholder, replacement);
  }
}

// Substituir placeholders de documentos
if (documentos.length > 0) {
  for (const doc of documentos) {
    const tipoDoc = doc.tipo === 'pdf' ? 'PDF' : doc.tipo || 'documento';
    const replacement = `${doc.placeholder}\n> 📋 **Documento (${tipoDoc}):** ${doc.resumo || doc.texto_extraido || 'Erro no resumo'}`;
    transcricao = transcricao.replace(doc.placeholder, replacement);
  }
}

// Contar mídias processadas
const totalMidias = audios.length + imagens.length + documentos.length;

// Atualizar resumo
const resumo = {
  ...prepData.resumo,
  midias: {
    audios: audios.length,
    imagens: imagens.length,
    documentos: documentos.length,
    total: totalMidias
  }
};

return [{
  json: {
    transcricao: transcricao,
    lead_nome: prepData.lead_nome,
    resumo: resumo,
    eventos: prepData.eventos,
    midias_processadas: {
      audios: audios,
      imagens: imagens,
      documentos: documentos
    },
    // Manter arrays originais para referência
    audios_para_transcrever: prepData.audios_para_transcrever || [],
    imagens_para_descrever: prepData.imagens_para_descrever || [],
    documentos_para_ler: prepData.documentos_para_ler || []
  }
}];

// Pega o array de documentos do item anterior
const documentos = $input.first().json.documentos_para_ler || [];

// Retorna cada documento como um item separado
return documentos.map(documento => ({
  json: {
    id: documento.id,
    url: documento.url,
    role: documento.role,
    tipo: documento.tipo || 'pdf'
  }
}));

// Pega o array de imagens do item anterior
const imagens = $input.first().json.imagens_para_descrever || [];

// Retorna cada imagem como um item separado
return imagens.map(imagem => ({
  json: {
    id: imagem.id,
    url: imagem.url,
    role: imagem.role
  }
}));

const audios = $input.first().json.audios_para_transcrever || [];

return audios.map(audio => ({
  json: {
    id: audio.id,
    url: audio.url,
    role: audio.role
  }
}));

// Pega todos os itens de transcrição
const transcricoes = $input.all();
// Pega todos os itens do Download Áudio (na mesma ordem)
const audiosDownload = $('Download Áudio').all();

// Combina cada transcrição com seu áudio correspondente
const resultados = transcricoes.map((item, index) => {
  const transcricao = item.json.text;
  const audioData = audiosDownload[index]?.json || {};

  return {
    json: {
      placeholder: audioData.id || '[AUDIO]',
      transcricao: transcricao,
      role: audioData.role || 'LEAD',
      tipo: 'audio'
    }
  };
});

return resultados;

